using System.Collections;

public class OMGInboundMessageMetadata extends common
{
}

Method.Source:
/// <summary>
/// Pupulates the OMGInboundMessageMetadata table with the metadata key-value pairs from the enumerator.
/// </summary>
/// <param name = "_messageGUID">The message GUID</param>
/// <param name = "_enumerator">The enumerator containing the metadata key-value pairs</param>
public static void createMetadata(OMGMessageGUID                    _messageGUID,
                                  System.Collections.IEnumerator    _enumerator)                                      
{
    OMGInboundMessageMetadata   messageMetadata;    
    OMGMetadataKey              metadataKey;
    OMGMetadataValue            metadataValue;

    while (_enumerator.MoveNext())
    {
        System.Object currentPair = _enumerator.Current;

        // Use .NET Reflection to bypass strict X++ compile-time property checks
        System.Type type = currentPair.GetType();

        metadataKey   = type.GetProperty('Key').GetValue(currentPair);
        metadataValue = type.GetProperty('Value').GetValue(currentPair);

        if (!OMGInboundMessageMetadata::exist(_messageGUID, metadataKey))
        {
            messageMetadata.clear();
            messageMetadata.initValue();
            messageMetadata.MessageGUID     = _messageGUID;
            messageMetadata.MetadataKey     = metadataKey;
            messageMetadata.MetadataValue   = metadataValue;
            messageMetadata.insert();
        }
    }
}

/// <summary>
/// Checks if a metadata key exists for a given message GUID.
/// </summary>
/// <param name = "_messageGUID">The message GUID</param>
/// <param name = "_metadataKey">The metadata key</param>
/// <returns>True if the metadata key exists for the given message GUID, otherwise false</returns>
public static boolean exist(OMGMessageGUID _messageGUID, 
                            OMGMetadataKey _metadataKey)
{                        
    return _messageGUID && _metadataKey &&
                (select firstonly RecId from OMGInboundMessageMetadata
                    where OMGInboundMessageMetadata.MessageGUID == _messageGUID   &&
                          OMGInboundMessageMetadata.MetadataKey == _metadataKey).RecId != 0;
}

/// <summary>
/// Finds a specific OMGInboundMessageMetadata record based on the message GUID and metadata key.
/// </summary>
/// <param name = "_messageGUID">The message GUID</param>
/// <param name = "_metadataKey">The metadata key</param>
/// <param name = "_forUpdate">Should the record be selected for update?</param>
/// <returns>The found OMGInboundMessageMetadata record</returns>
public static OMGInboundMessageMetadata find(OMGMessageGUID _messageGUID, 
                                             OMGMetadataKey _metadataKey,
                                             boolean        _forUpdate = false)
{
    OMGInboundMessageMetadata messageMetadata;

    messageMetadata.selectForUpdate(_forUpdate);

    if (_messageGUID && _metadataKey)
    {
        select firstonly messageMetadata
            where messageMetadata.MessageGUID == _messageGUID &&
                  messageMetadata.MetadataKey == _metadataKey;
    }
    return messageMetadata;
}
